/* =========================
   GLOBAL PLANET DATA
========================= */

var planets = ["sun","mercury","venus","earth","mars","jupiter","saturn","uranus","neptune"];
var currentIndex = 3; // Default Earth
var selectedPlanet = "earth";


/* =========================
   PLANET OPTIONS POPUP
========================= */

function openPlanet(planet){
  selectedPlanet = planet;

  var title = document.getElementById("optionTitle");
  var popup = document.getElementById("planetOptions");

  if(title && popup){
    title.innerText = planet.charAt(0).toUpperCase() + planet.slice(1);
    popup.classList.add("show");
  }
}

function closeOptions(){
  var popup = document.getElementById("planetOptions");
  if(popup){
    popup.classList.remove("show");
  }
}

/* ✅ FIXED */
function showPlanetInfo(){
  closeOptions();
  window.open(selectedPlanet + "_info.html", "_blank");
}

/* ✅ FIXED */
function goToVideo(){
  closeOptions();
  window.open(selectedPlanet + ".html", "_blank");
}


/* =========================
   BOT PANEL
========================= */

function openBot(){
  closeOptions();
  var bot = document.getElementById("chatBot");
  if(bot){
    bot.classList.add("show");
  }
}

function closeBot(){
  var bot = document.getElementById("chatBot");
  if(bot){
    bot.classList.remove("show");
  }
}

function askBot(){

  var input = document.getElementById("botInput");
  var responseBox = document.getElementById("botResponse");

  if(!input || !responseBox) return;

  var question = input.value.toLowerCase();
  var response = "I don't understand your question.";

  if(question.includes("size")){
    response = selectedPlanet + " has a unique size in our solar system.";
  }
  else if(question.includes("distance")){
    response = selectedPlanet + " has its own distance from the Sun.";
  }
  else if(question.includes("moon")){
    response = selectedPlanet + " may have moons depending on the planet.";
  }
  else if(question.includes("temperature")){
    response = selectedPlanet + " has extreme temperature conditions.";
  }

  responseBox.innerText = response;
}


/* =========================
   MAIN 3D SOLAR SYSTEM LOGIC
========================= */

$(document).ready(function(){

  var body = $("body");
  var universe = $("#universe");
  var solarsys = $("#solar-system");

  function init() {
    body.removeClass('view-2D opening')
        .addClass("view-3D")
        .delay(2000)
        .queue(function() {
          $(this).removeClass('hide-UI')
                 .addClass("set-speed");
          $(this).dequeue();
        });

    updatePlanet();
  }

  function updatePlanet(){
    var planet = planets[currentIndex];
    selectedPlanet = planet;

    if(solarsys.length){
      solarsys.removeClass().addClass(planet);
    }

    var currentPlanetText = document.getElementById("currentPlanet");
    if(currentPlanetText){
      currentPlanetText.innerText =
        planet.charAt(0).toUpperCase() + planet.slice(1);
    }

    body.removeClass("data-close").addClass("data-open");
  }

  $("#prevPlanet").click(function(){
    currentIndex--;
    if(currentIndex < 0) currentIndex = planets.length - 1;
    updatePlanet();
  });

  $("#nextPlanet").click(function(){
    currentIndex++;
    if(currentIndex >= planets.length) currentIndex = 0;
    updatePlanet();
  });

  $("#toggle-data").click(function(e) {
    e.preventDefault();
    body.toggleClass("data-open data-close");
  });

  $("#toggle-controls").click(function(e) {
    e.preventDefault();
    body.toggleClass("controls-open controls-close");
  });

  $(".set-view").click(function() {
    body.toggleClass("view-3D view-2D");
  });

  $(".set-zoom").click(function() {
    body.toggleClass("zoom-large zoom-close");
  });

  $(".set-speed").click(function() {
    universe.removeClass().addClass("scale-stretched set-speed");
  });

  $(".set-size").click(function() {
    universe.removeClass().addClass("scale-s set-size");
  });

  $(".set-distance").click(function() {
    universe.removeClass().addClass("scale-d set-distance");
  });

  init();
});
/* AI PANEL OPEN/CLOSE */

const aiButton = document.getElementById("aiRobotButton");
const aiPanel = document.getElementById("aiRobotPanel");
const closeAI = document.getElementById("closeAI");

aiButton.onclick = () => aiPanel.style.display="flex";
closeAI.onclick = () => aiPanel.style.display="none";


/* SEND MESSAGE */

document.getElementById("sendAI").onclick = sendAI;

async function sendAI(){

const input = document.getElementById("aiInput");
const messages = document.getElementById("aiMessages");

let text = input.value;

if(!text) return;

messages.innerHTML += `<div><b>You:</b> ${text}</div>`;

input.value="";

const response = await fetch("/ask-ai",{
method:"POST",
headers:{ "Content-Type":"application/json"},
body:JSON.stringify({message:text})
});

const data = await response.json();

messages.innerHTML += `<div class="ai-bot">${data.reply}</div>`;

messages.scrollTop = messages.scrollHeight;

}
function robotAnswer(){

let q = document.getElementById("robotInput").value.toLowerCase();
let reply = "";

if(q.includes("earth")){
reply = "Earth is the third planet from the Sun and the only known planet with life.";
}

else if(q.includes("mars")){
reply = "Mars is known as the Red Planet.";
}

else if(q.includes("jupiter")){
reply = "Jupiter is the largest planet in the solar system.";
}

else if(q.includes("saturn")){
reply = "Saturn is famous for its rings.";
}

else{
reply = "Ask me about planets like Earth, Mars, Jupiter or Saturn.";
}

document.getElementById("robotMessage").innerText = reply;

}